with recent_accounts as (select * from accounts where account_type not in ('LOAN', 'CHECKING', 'SAVINGS') and opened_date <= '2023-03-16'), agg as (select status, year(opened_date) as opened_year, count(case when status = 'FROZEN' then 1 end) as frozen_count from recent_accounts group by status, year(opened_date)) select status, opened_year from agg where frozen_count < 8 order by opened_year desc
